def LOCF(x):
    """Last observation carried forward."""
    y = x.copy()
    for i in range(1, len(y)):
        if np.isnan(y[i]):
            y[i] = y[i - 1]
    return y

def NOCB(x):
    """Next observation carried backward."""
    y = x.copy()
    for i in range(len(y) - 2, -1, -1):
        if np.isnan(y[i]):
            y[i] = y[i + 1]
    return y
